package de.corporate.lc.lc.service; import de.corporate.lc.lc.domain.*; import de.corporate.lc.lc.repository.*; import de.corporate.lc.swift.Mt707Parser; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AmendmentService {private final AmendmentRepository amendments;private final LetterOfCreditRepository lcs;private final Mt707Parser parser;public AmendmentService(AmendmentRepository a,LetterOfCreditRepository l,Mt707Parser p){amendments=a;lcs=l;parser=p;}@Transactional public Amendment importMt707(String raw){var p=parser.parse(raw);LetterOfCredit lc=lcs.findByReference(p.lcReference()).orElseThrow(()->new IllegalArgumentException("Original LC not found: "+p.lcReference()));Amendment a=p.amendment();a.setLetterOfCredit(lc);if(a.getNewExpiryDate()!=null){lc.setExpiryDate(a.getNewExpiryDate());if(a.getNewExpiryPlace()!=null&&!a.getNewExpiryPlace().isBlank())lc.setExpiryPlace(a.getNewExpiryPlace());}if(a.getNewLatestShipmentDate()!=null)lc.setLatestShipmentDate(a.getNewLatestShipmentDate());if(a.getAmountIncrease()!=null&&lc.getAmount()!=null)lc.setAmount(lc.getAmount().add(a.getAmountIncrease()));if(a.getAmountDecrease()!=null&&lc.getAmount()!=null)lc.setAmount(lc.getAmount().subtract(a.getAmountDecrease()));applyDocumentChanges(lc,a.getChangedDocuments());lcs.save(lc);return amendments.save(a);}void applyDocumentChanges(LetterOfCredit lc,String changes){if(changes==null||changes.isBlank())return;List<String> current=new ArrayList<>(lc.getRequiredDocuments());boolean replace=changes.toUpperCase(Locale.ROOT).contains("/REPALL/")||changes.toUpperCase(Locale.ROOT).contains("REPLACE ALL");if(replace)current.clear();for(String raw:changes.split("\\R")){String line=raw.trim();if(line.isBlank()||line.equalsIgnoreCase("/REPALL/")||line.equalsIgnoreCase("REPLACE ALL"))continue;String upper=line.toUpperCase(Locale.ROOT);if(line.startsWith("+")||upper.startsWith("/ADD/")){String value=line.startsWith("+")?line.substring(1).trim():line.substring(5).trim();if(!value.isBlank()&&current.stream().noneMatch(x->same(x,value)))current.add(value);}else if(line.startsWith("-")||upper.startsWith("/DELETE/")){String value=line.startsWith("-")?line.substring(1).trim():line.substring(8).trim();current.removeIf(existing->same(existing,value));}else if(replace)current.add(line);}lc.setRequiredDocuments(current);}private boolean same(String a,String b){return a.replaceAll("[^A-Za-z0-9]","").equalsIgnoreCase(b.replaceAll("[^A-Za-z0-9]",""));}public List<Amendment> forLc(UUID id){return amendments.findByLetterOfCreditIdOrderByImportedAtDesc(id);}}
